import{_ as a,o as s,c as n,a4 as o}from"./chunks/framework.BRzJ4ijD.js";const g=JSON.parse('{"title":"分布式事务: 2PC / Saga / TCC / Outbox / Spanner","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/transactions.md","filePath":"distributed/transactions.md","lastUpdated":1788475713000}'),e={name:"distributed/transactions.md"};function r(l,t,p,i,d,c){return s(),n("div",null,[...t[0]||(t[0]=[o(`<h1 id="分布式事务-2pc-saga-tcc-outbox-spanner" tabindex="-1">分布式事务: 2PC / Saga / TCC / Outbox / Spanner <a class="header-anchor" href="#分布式事务-2pc-saga-tcc-outbox-spanner" aria-label="Permalink to &quot;分布式事务: 2PC / Saga / TCC / Outbox / Spanner&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>单机事务靠 WAL + 锁把&quot;多行修改&quot;原子化；一旦数据分到多台机器（微服务拆分、分库分表），<strong>&quot;跨库转账&quot;这类操作需要跨机器原子性</strong>。这一章讲四条技术路线的数学本质与工程取舍：<strong>2PC</strong>（强一致，但协调者故障会阻塞）、<strong>Saga</strong>（无原子性，靠补偿最终一致）、<strong>TCC</strong>（业务把&quot;预留/确认/取消&quot;三阶段暴露出来）、<strong>Outbox/事务消息</strong>（把 DB 事务和消息投递绑成一个原子操作）。最后看 Google Spanner 怎么用 <strong>2PC + TrueTime</strong> 同时拿到强一致和可用性。工程上 90% 的&quot;分布式事务&quot;问题，正确答案是<strong>换一个不用跨库事务的数据模型</strong>，而不是引入 2PC。</p><p>读完应能：</p><ol><li>复述 2PC 的两阶段流程，指出协调者/参与者各自故障时的阻塞点与可恢复性。</li><li>说出 3PC 比 2PC 好在哪、为什么没解决根本问题。</li><li>设计一个 Saga（含补偿顺序）和一个 TCC 接口（Try/Confirm/Cancel + 幂等 + 空回滚）。</li><li>说清 Outbox 为什么能保证&quot;DB 写入与消息投递至少一次一致&quot;，以及消费侧怎么幂等。</li><li>判断一个业务场景到底该用 2PC / Saga / TCC / 还是重构避免。</li></ol><hr><h2 id="一、问题定义-分布式原子提交" tabindex="-1">一、问题定义: 分布式原子提交 <a class="header-anchor" href="#一、问题定义-分布式原子提交" aria-label="Permalink to &quot;一、问题定义: 分布式原子提交&quot;">​</a></h2><p>把转账拆成&quot;扣 A 账户&quot;（库 1）+&quot;加 B 账户&quot;（库 2）。两边各自有本地事务，但<strong>没有一个共同的锁/WAL 能同时覆盖两库</strong>。需要协议保证：要么两边都提交，要么两边都回滚，且任何进程崩溃后仍能收敛。</p><p>这就是 <strong>分布式原子提交（Distributed Atomic Commit）</strong> 问题。注意它和共识（consensus）的区别：</p><table tabindex="0"><thead><tr><th></th><th>共识 (Paxos/Raft)</th><th>原子提交 (2PC)</th></tr></thead><tbody><tr><td>问什么</td><td>多节点对一个<strong>值</strong>达成一致</td><td>多节点对<strong>是否提交</strong>各自的事务达成一致</td></tr><tr><td>失败模型</td><td>容忍故障，总能推进</td><td>协调者故障时可能<strong>阻塞</strong></td></tr><tr><td>典型产物</td><td>复制状态机、选主</td><td>XA、数据库两阶段</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>2PC 每轮都要多数派之外的全部参与者点头，且协调者是单点——它解决的是&quot;原子性&quot;而不是&quot;可用性&quot;。把 2PC 当共识用是常见误解。</p></div><h2 id="二、2pc-准备-→-提交" tabindex="-1">二、2PC: 准备 → 提交 <a class="header-anchor" href="#二、2pc-准备-→-提交" aria-label="Permalink to &quot;二、2PC: 准备 → 提交&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>协调者(Coordinator)               参与者(Participants)</span></span>
<span class="line"><span>   │  prepare(tx) ───────────────────►│ ① 写 undo/redo 日志, 加锁</span></span>
<span class="line"><span>   │◄───────────  yes / no ───────────│ ② 进入 prepared 状态, 可恢复</span></span>
<span class="line"><span>   │  如果全部 yes:                     │</span></span>
<span class="line"><span>   │  commit ────────────────────────►│ ③ 释放锁, 提交</span></span>
<span class="line"><span>   │  (任一 no: 发 abort)</span></span></code></pre></div><p>两个阶段的关键性质：</p><ol><li><strong>准备阶段</strong>：参与者把事务做成&quot;可提交但未提交&quot;（写日志 + 持锁）。此时承诺：只要收到 commit 就一定提交；</li><li><strong>提交阶段</strong>：协调者已决定，全体执行。<strong>决策一旦做出，协议不允许反悔</strong>。</li></ol><p>故障分析（这是面试/设计题核心）：</p><table tabindex="0"><thead><tr><th>故障</th><th>后果</th><th>恢复方式</th></tr></thead><tbody><tr><td>参与者 prepare 后崩溃</td><td>持有锁，事务悬挂</td><td>重启后查日志，等协调者补发 commit/abort</td></tr><tr><td>协调者在 prepare 后、commit 前崩溃</td><td><strong>所有参与者阻塞</strong>，资源被锁死</td><td>需要新协调者读日志恢复决策；否则只能人工介入</td></tr><tr><td>参与者收 commit 后崩溃</td><td>事务已提交，但副本可能未同步</td><td>重放日志 + 对下游补偿</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>2PC 的&quot;不可用&quot;不是概率事件：协调者故障 + 网络分区时，参与者既不能提交也不敢回滚（怕违背承诺），只能干等。这就是&quot;阻塞问题&quot;，也是 2PC 不适合长事务/跨公网的原因。</p></div><h3 id="_3pc-的有限改进" tabindex="-1">3PC 的有限改进 <a class="header-anchor" href="#_3pc-的有限改进" aria-label="Permalink to &quot;3PC 的有限改进&quot;">​</a></h3><p>3PC 在 2PC 前加一轮 <strong>can-commit</strong>（投票），并把提交阶段拆成 <strong>pre-commit → do-commit</strong>，让参与者之间可以&quot;互相恢复&quot;（任何一个知道超时都可以去问别人）。它解决了协调者单点崩溃导致的无限阻塞，但：</p><ul><li>网络分区 + 新主视图不一致时仍可能<strong>脑裂</strong>（有人提交有人回滚）；</li><li>工程上几乎没人用纯 3PC，因为引入的复杂度大于收益。</li></ul><h2 id="三、xa-2pc-的工业实现" tabindex="-1">三、XA: 2PC 的工业实现 <a class="header-anchor" href="#三、xa-2pc-的工业实现" aria-label="Permalink to &quot;三、XA: 2PC 的工业实现&quot;">​</a></h2><p>Java 世界用 XA 接口把数据库/消息中间件接进 2PC：<code>xa_start / xa_end / xa_prepare / xa_commit / xa_rollback</code>。MySQL/PostgreSQL/Oracle 都支持。</p><p>现实中的 XA 代价：</p><ul><li>每个参与者在 prepare 后<strong>锁资源直到全局决策</strong>——两库场景下并发和吞吐暴跌；</li><li>协调者（如应用进程）是单点且必须持久化事务表，否则重启即失忆；</li><li>跨库性能问题、运维事故频发，业界（尤其互联网公司）<strong>用 XA 的比例很低</strong>。</li></ul><blockquote><p>结论：XA/2PC 适合&quot;少量短事务 + 强一致 + 内部低延迟网络&quot;的场景（典型：银行核心、数据中心内两库联动），不适合跨公网、长事务、高并发互联网业务。</p></blockquote><h2 id="四、saga-没有原子性-用补偿" tabindex="-1">四、Saga: 没有原子性，用补偿 <a class="header-anchor" href="#四、saga-没有原子性-用补偿" aria-label="Permalink to &quot;四、Saga: 没有原子性，用补偿&quot;">​</a></h2><p>Saga 把一个大事务拆成 N 个<strong>本地事务</strong> + 每个本地事务配一个<strong>补偿事务</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下单(库存扣减) → 生成订单 → 支付扣款</span></span>
<span class="line"><span>失败则反向补偿:  支付失败 → 取消订单 → 库存回补</span></span></code></pre></div><p>两种编排：</p><table tabindex="0"><thead><tr><th>编排方式</th><th>控制流</th><th>优缺点</th></tr></thead><tbody><tr><td><strong>Choreography（事件驱动）</strong></td><td>每个服务完成后发事件，下一个服务订阅</td><td>无中心点、演进灵活；但流程不可见、难调试</td></tr><tr><td><strong>Orchestration（编排器）</strong></td><td>中央 Saga 编排器依次调用</td><td>流程集中可见、易做重试/超时；编排器本身要高可用</td></tr></tbody></table><p>正确性三要素：</p><ol><li><strong>补偿必须能成功</strong>：补偿里不能依赖&quot;对方也失败&quot;等假设，要设计成幂等、可重试；</li><li><strong>补偿顺序 = 正序逆序</strong>：<code>t1, t2, t3</code> 失败于 t3 → 补偿 <code>c3, c2, c1</code>（c3 通常是被动补偿，t3 自己的回滚）；</li><li><strong>无隔离保证</strong>：Saga 中间状态对外可见——需要额外手段（如订单状态机 + 对账）控制。</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>面试/设计高频答案：<strong>Saga 适用于&quot;最终一致可接受、链路长、跨多个独立服务&quot;</strong>。先画状态机，再定补偿，最后用幂等键 + 对账脚本兜底。</p></div><h2 id="五、tcc-把三阶段暴露给业务" tabindex="-1">五、TCC: 把三阶段暴露给业务 <a class="header-anchor" href="#五、tcc-把三阶段暴露给业务" aria-label="Permalink to &quot;五、TCC: 把三阶段暴露给业务&quot;">​</a></h2><p>TCC（Try-Confirm-Cancel）把 2PC 的 prepare/commit 翻译成业务操作：</p><table tabindex="0"><thead><tr><th>阶段</th><th>做什么</th><th>例子（库存扣减）</th></tr></thead><tbody><tr><td><strong>Try</strong></td><td>预留资源，不真正生效</td><td>冻结库存 10 件</td></tr><tr><td><strong>Confirm</strong></td><td>确认生效（幂等）</td><td>把冻结转成实际扣减</td></tr><tr><td><strong>Cancel</strong></td><td>释放预留（幂等）</td><td>解冻 10 件</td></tr></tbody></table><p>必须处理的三个边界：</p><ol><li><strong>幂等</strong>：Confirm/Cancel 可能因网络重试被调多次，业务侧要用事务 ID 去重；</li><li><strong>空回滚</strong>：Try 因超时没真正执行，但 Cancel 到了——Cancel 必须能安全执行（通常查无此预留就返回成功）；</li><li><strong>悬挂</strong>：Cancel 先到、Try 后到——要拒绝迟到的 Try（记录已 Cancel）。</li></ol><p>主流实现：Seata AT/TCC 模式、DTM。TCC 的代价是把业务逻辑改造成&quot;预留/确认/取消&quot;三段——<strong>侵入性强，适合余额、库存、优惠券这类天然可分阶段操作的资源</strong>。</p><h2 id="六、outbox-事务消息-最容易落地的-半分布式事务" tabindex="-1">六、Outbox / 事务消息: 最容易落地的&quot;半分布式事务&quot; <a class="header-anchor" href="#六、outbox-事务消息-最容易落地的-半分布式事务" aria-label="Permalink to &quot;六、Outbox / 事务消息: 最容易落地的&quot;半分布式事务&quot;&quot;">​</a></h2><p>最常用的需求其实是：&quot;<strong>DB 写成功 + 发消息/事件成功</strong>&quot;（比如下单后发 Kafka 事件给下游）。两个操作跨系统，朴素做法是&quot;先写库再发消息&quot;，但二者之间崩溃就丢事件。</p><p><strong>Transactional Outbox</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>业务事务:  INSERT 订单;  INSERT outbox(事件)   ← 同一个本地事务</span></span>
<span class="line"><span>后台任务:  扫 outbox → 发 Kafka → 标记已发送</span></span></code></pre></div><p>关键性质：<strong>事件和业务数据在同一个本地事务里落库</strong>，要么都成要么都败；投递用 at-least-once，消费侧<strong>幂等去重</strong>。</p><p>工程要点：</p><ul><li>outbox 表要<strong>批次扫描 + 索引</strong>（未发送状态 + 创建时间），避免拖慢业务写；</li><li>发送后<strong>删除或标记</strong>（标记更稳，可审计）；</li><li>对 Kafka 的&quot;事务消息&quot;（producer transaction）做跨系统原子，本质上仍是 outbox 的变体，且要求 Kafka 与 DB 之间有协调者——多数团队直接选 outbox；</li><li>高吞吐替代：**CDC（Debezium 监听 binlog）**把 outbox 变成事件流，避免轮询。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Outbox 解决了&quot;原子性&quot;（写库和发事件二选一），但没有解决&quot;两个系统都强一致提交&quot;——如果下游必须和上游同时可见（如分布式账本），它不够；如果只是&quot;通知/异步解耦&quot;，它就是最佳工程答案。</p></div><h2 id="七、spanner-2pc-truetime-的强一致组合拳" tabindex="-1">七、Spanner: 2PC + TrueTime 的强一致组合拳 <a class="header-anchor" href="#七、spanner-2pc-truetime-的强一致组合拳" aria-label="Permalink to &quot;七、Spanner: 2PC + TrueTime 的强一致组合拳&quot;">​</a></h2><p>Google Spanner 并没有发明新共识，而是<strong>把 2PC 放进 Paxos 组</strong>：</p><ol><li>每个分片是一个 Paxos 复制组（leader 在多数派中）；</li><li>跨分片事务仍走 <strong>2PC</strong>，但协调者/参与者故障由 Paxos 复制接管；</li><li>commit wait 用 <strong>TrueTime 时间戳</strong>（GPS + 原子钟）保证 external consistency：提交时间戳晚于所有并发事务，从而让读在任意节点都能看到&quot;截至某时间点的全部已提交事务&quot;。</li></ol><p>工程启示：<strong>2PC 的可用性短板可以用共识层补</strong>（协调者高可用 + 状态复制），但代价是每个分片都要跑 Paxos——这不是&quot;免费强一致&quot;，而是把成本摊到基础设施。</p><h2 id="八、选型决策树" tabindex="-1">八、选型决策树 <a class="header-anchor" href="#八、选型决策树" aria-label="Permalink to &quot;八、选型决策树&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>真的需要跨系统原子提交吗?</span></span>
<span class="line"><span>├─ 不需要 → 拆分/重设计 (把两写变成一写 + 异步)  ← 默认答案</span></span>
<span class="line"><span>├─ 需要强一致, 且网络可控、事务短</span></span>
<span class="line"><span>│    └─ XA/2PC (数据中心内, 少参与者)</span></span>
<span class="line"><span>├─ 需要强一致, 且要容错高可用</span></span>
<span class="line"><span>│    └─ Spanner 式: 2PC + Paxos + TrueTime</span></span>
<span class="line"><span>├─ 最终一致可接受, 长链路业务</span></span>
<span class="line"><span>│    └─ Saga (编排器 + 补偿 + 幂等)</span></span>
<span class="line"><span>├─ 资源型操作 (库存/余额/优惠券)</span></span>
<span class="line"><span>│    └─ TCC (Try/Confirm/Cancel + 空回滚 + 悬挂处理)</span></span>
<span class="line"><span>└─ 只要&quot;写库+发消息&quot;原子</span></span>
<span class="line"><span>     └─ Transactional Outbox / CDC</span></span></code></pre></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>最常见的架构错误：为了&quot;两个表跨库强一致&quot;引入 XA，结果 3 个月后因为锁阻塞把系统拖死。先量化真实需求——<strong>允许 1 秒延迟的一致</strong>和&quot;绝对不能不一致&quot;是两个量级完全不同的工程。</p></div><h2 id="九、一页速查" tabindex="-1">九、一页速查 <a class="header-anchor" href="#九、一页速查" aria-label="Permalink to &quot;九、一页速查&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2PC:  prepare 全票 → commit; 协调者故障 = 阻塞; 适合数据中心内短事务</span></span>
<span class="line"><span>3PC:  多一轮投票 + pre-commit, 减少阻塞但可能脑裂, 工程少见</span></span>
<span class="line"><span>Saga: 本地事务 + 补偿, 无原子性, 编排器/事件驱动, 幂等 + 对账</span></span>
<span class="line"><span>TCC:  Try 预留 / Confirm 生效 / Cancel 回滚, 幂等 + 空回滚 + 防悬挂</span></span>
<span class="line"><span>Outbox: 业务写 + 事件写同一个本地事务, at-least-once + 消费幂等</span></span>
<span class="line"><span>Spanner: 2PC 每分片跑 Paxos + TrueTime commit wait = external consistency</span></span>
<span class="line"><span>选型: 默认重构避免; 强一致短事务=2PC; 最终一致长链路=Saga; 资源型=TCC</span></span></code></pre></div><p>下一篇: <a href="./fault/">分布式存储与容错</a>。</p>`,58)])])}const h=a(e,[["render",r]]);export{g as __pageData,h as default};
